def list_to_roots(apps, schema_editor):
    Rule = apps.get_model("grow", "GenreEdgeRule")
    Entry = apps.get_model("grow", "CurationEntry")
    for entry in Entry.objects.filter(list_name=ROOTS):
        # A canonical_parent rule that gained a parent since is kept as is: the item has a parent, so it is no
        # longer a root and the entry has nothing to restore.
        Rule.objects.get_or_create(
            user=entry.user,
            relation="canonical_parent",
            item_id=entry.key,
            defaults={"parent_item_id": None, "exclude_other_parents": True, "reason": entry.reason},
        )
    Entry.objects.filter(list_name=ROOTS).delete()
    apps.get_model("grow", "CurationReviewItem").objects.filter(list_name=ROOTS).delete()
    fire_deferred_constraints(schema_editor)


def keep_last_export(apps, schema_editor):
    """The former singleton's date stays usable for the pending tree; its content was never recorded."""
    State = apps.get_model("grow", "CurationSyncState")
    Export = apps.get_model("grow", "CurationExport")
    state = State.objects.filter(pk=1).first()
    if state is not None and state.exported_on is not None:
        Export.objects.get_or_create(exported_on=state.exported_on, defaults={"snapshot": None})


def restore_last_export(apps, schema_editor):
    State = apps.get_model("grow", "CurationSyncState")
    Export = apps.get_model("grow", "CurationExport")
    latest = Export.objects.order_by("-exported_on").first()
    if latest is not None:
        State.objects.filter(pk=1).update(exported_on=latest.exported_on)


